// ===========================================

import { useState } from "react";
function Task5() {
  const price = 500;
  const [quantity, setQuantity] = useState(1);
  const totalPrice = price * quantity;
  function increase() {
    setQuantity(quantity + 1);
  }

  function decrease() {
    if(quantity>1){
        setQuantity(quantity-1)
    }
  }

  function reset() {
    setQuantity(1);
  }
  return (
    <div>
      <h2>Product Price: ₹{price}</h2>
      <button onClick={decrease}>Decrease Qty</button>
      <span style={{marginLeft:"10px",marginRight:"10px",fontSize:"22px",color:"red"}}>{quantity}</span>
      <button onClick={increase}>Increase Qty</button>
      <button onClick={reset}>Reset</button>
      <h3>Total: ₹{totalPrice}</h3>
    </div>
  );
}

export default Task5;